import React, { useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import useAppStore from '../store';
import {
  LayoutDashboard, Map, MessageSquare, FileText, Code2,
  AlertCircle, BookOpen, Users, BarChart3, LogOut,
  Bell, Brain, ChevronDown, Shield
} from 'lucide-react';

const STUDENT_NAV = [
  { path: '/dashboard', icon: LayoutDashboard, label: 'Dashboard' },
  { path: '/roadmap', icon: Map, label: 'My Roadmap' },
  { path: '/mentor', icon: MessageSquare, label: 'AI Mentor' },
  { path: '/documents', icon: FileText, label: 'Documents' },
  { path: '/coding', icon: Code2, label: 'Coding Profile' },
  { path: '/disputes', icon: AlertCircle, label: 'Disputes' },
];

const TEACHER_NAV = [
  { path: '/teacher/classes', icon: Users, label: 'My Classes' },
  { path: '/teacher/assignments', icon: BookOpen, label: 'Assignments' },
  { path: '/teacher/attendance', icon: BarChart3, label: 'Attendance' },
  { path: '/teacher/alerts', icon: Bell, label: 'Risk Alerts' },
];

const ADMIN_NAV = [
  { path: '/admin/analytics', icon: BarChart3, label: 'Analytics' },
  { path: '/admin/disputes', icon: AlertCircle, label: 'Disputes' },
  { path: '/admin/users', icon: Users, label: 'User Management' },
];

function NavItem({ path, icon: Icon, label }) {
  const location = useLocation();
  const active = location.pathname === path || location.pathname.startsWith(path + '/');

  return (
    <Link 
      to={path} 
      className={`nav-item-premium ${active ? 'active' : ''}`}
    >
      <Icon size={18} className={active ? 'text-violet-400' : 'text-slate-500'} />
      <span className="font-semibold">{label}</span>
      {active && <div className="ml-auto w-1.5 h-1.5 rounded-full bg-violet-400 shadow-[0_0_8px_rgba(139,92,246,0.8)]" />}
    </Link>
  );
}

export default function Layout({ children }) {
  const { currentUser, role, logout } = useAppStore();
  const [notifOpen, setNotifOpen] = useState(false);

  const navItems = role === 'student' ? STUDENT_NAV : role === 'teacher' ? TEACHER_NAV : ADMIN_NAV;

  // Custom roles rendering logic safely with optional chaining
  const roleLabel = role === 'student' ? 'Student' : role === 'teacher' ? 'Faculty' : 'Admin';
  const roleColorCls = role === 'student' ? 'text-sky-400 border-sky-400/30 bg-sky-400/10' : 
                       role === 'teacher' ? 'text-violet-400 border-violet-400/30 bg-violet-400/10' : 
                                            'text-teal-400 border-teal-400/30 bg-teal-400/10';

  return (
    <div className="flex h-screen overflow-hidden bg-[#030014] text-slate-100 font-inter font-sans">

      {/* Sidebar background glow effect */}
      <div className="absolute top-0 left-0 w-[400px] h-[400px] bg-violet-600/10 blur-[120px] rounded-full pointer-events-none -z-10" />

      {/* Sidebar - Glassmorphic */}
      <aside className="w-[260px] flex-shrink-0 flex flex-col border-r border-white/10 glass-panel z-10 relative">

        {/* Logo Section */}
        <div className="p-6 border-b border-white/10 backdrop-blur-md">
          <div className="flex items-center gap-3">
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-violet-600 to-sky-600 flex items-center justify-center shadow-[0_0_20px_rgba(139,92,246,0.5)]">
              <Brain size={22} className="text-white" />
            </div>
            <span className="text-xl font-bold font-space tracking-tight text-white">Veloris</span>
          </div>
          <div className="mt-4 flex items-center gap-2">
            <span className={`text-xs px-2.5 py-0.5 rounded-full font-bold border flex items-center gap-1.5 ${roleColorCls}`}>
              {role === 'student' ? "🎓" : role === 'teacher' ? "👨‍🏫" : "🛡️"} {roleLabel}
            </span>
          </div>
        </div>

        {/* Navigation */}
        <nav className="flex-1 px-4 py-6 flex flex-col gap-1.5 overflow-y-auto custom-scrollbar">
          <div className="text-xs font-bold text-slate-500 uppercase tracking-widest px-4 mb-2">
            Main Menu
          </div>
          {navItems.map((item) => <NavItem key={item.path} {...item} />)}
        </nav>

        {/* User Card */}
        <div className="p-4 border-t border-white/10">
          <div className="flex items-center gap-3 p-3 rounded-xl bg-white/5 border border-white/5 hover:border-white/10 transition-colors">
            <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold shrink-0 ${roleColorCls}`}>
              {currentUser?.avatar}
            </div>
            <div className="flex-1 min-w-0">
              <div className="text-sm font-bold text-slate-200 truncate">{currentUser?.name}</div>
              <div className="text-xs text-slate-400 truncate">{currentUser?.email}</div>
            </div>
            <button 
              onClick={logout} 
              className="p-2 -mr-1 text-slate-400 hover:text-rose-400 hover:bg-rose-400/10 rounded-lg transition-colors group" 
              title="Logout"
            >
              <LogOut size={16} className="group-hover:-translate-x-0.5 transition-transform" />
            </button>
          </div>
        </div>
      </aside>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col overflow-hidden relative z-0">

        {/* Top Header - Glass Navbar */}
        <header className="h-[72px] shrink-0 border-b border-white/10 glass-elevated px-8 flex items-center justify-between sticky top-0 z-20">

          <div className="flex-1">
            {/* Search or Breadcrumbs can go here */}
            <div className="relative max-w-md hidden sm:block">
              <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                <svg className="h-4 w-4 text-slate-500" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input type="text" className="input-premium pl-10 h-10 py-2 w-full max-w-sm rounded-[10px]" placeholder={`Search ${roleLabel} dashboard...`} />
            </div>
          </div>

          <div className="flex items-center gap-5">
            {/* Notifications */}
            {role !== 'admin' && (
              <button 
                onClick={() => setNotifOpen(!notifOpen)} 
                className="relative w-10 h-10 rounded-xl bg-white/5 border border-white/10 flex items-center justify-center text-slate-300 hover:text-white hover:bg-white/10 transition-all hover:shadow-[0_0_15px_rgba(255,255,255,0.1)]"
              >
                <Bell size={18} />
                <span className="absolute top-2.5 right-2.5 w-2 h-2 rounded-full bg-rose-500 shadow-[0_0_6px_rgba(244,63,94,0.8)] animate-pulse" />
              </button>
            )}

            <div className="h-6 w-px bg-white/10" />

            {/* User Profile Mini */}
            <div className="flex items-center gap-3 cursor-pointer group">
              <div className="text-right hidden md:block">
                <div className="text-sm font-bold text-slate-200 group-hover:text-white transition-colors">{currentUser?.name?.split(' ')[0]}</div>
                <div className="text-[10px] text-slate-400 tracking-wider uppercase">{currentUser?.rollNo || roleLabel}</div>
              </div>
              <div className={`w-9 h-9 rounded-full flex items-center justify-center text-xs font-bold border shadow-lg ${role === 'student' ? 'border-sky-500/30' : 'border-violet-500/30'} ${roleColorCls}`}>
                {currentUser?.avatar}
              </div>
              <ChevronDown size={14} className="text-slate-500 group-hover:text-slate-300 transition-colors" />
            </div>
          </div>
        </header>

        {/* Content Body */}
        <main className="flex-1 overflow-y-auto relative custom-scrollbar">
          {/* Main radiant background for content */}
          <div className="absolute top-[-10%] right-[-5%] w-[600px] h-[600px] bg-sky-500/10 blur-[150px] rounded-full pointer-events-none -z-10" />

          <div className="p-8 max-w-[1600px] mx-auto z-10 fade-in-up">
            {children}
          </div>
        </main>
      </div>
    </div>
  );
}

import React from 'react';
import { MOCK_STUDENTS } from '../../store';
import { PageHeader, StatCard } from '../../components/UI';
import { PieChart, Pie, Cell, Tooltip, ResponsiveContainer, BarChart, Bar, XAxis, YAxis, CartesianGrid, AreaChart, Area } from 'recharts';
import { Users, TrendingUp, AlertTriangle, CheckCircle2 } from 'lucide-react';

const riskDist = [
  { name: 'Low Risk', value: 2, color: '#22c55e' },
  { name: 'At Watch', value: 2, color: '#f59e0b' },
  { name: 'At Risk', value: 1, color: '#ef4444' },
];

const attendanceTrend = [
  { month: 'Nov', avg: 88 }, { month: 'Dec', avg: 85 }, { month: 'Jan', avg: 82 },
  { month: 'Feb', avg: 79 }, { month: 'Mar', avg: 76 },
];

const branchData = [
  { branch: 'CSE-A', avg: 74, students: 4 },
  { branch: 'CSE-B', avg: 91, students: 1 },
  { branch: 'ECE-A', avg: 82, students: 0 },
  { branch: 'MECH-A', avg: 79, students: 0 },
];

const CustomPieLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent, name }) => {
  const RADIAN = Math.PI / 180;
  const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);
  return (
    <text x={x} y={y} fill="white" textAnchor="middle" dominantBaseline="central" fontSize={11} fontWeight={600}>
      {`${(percent * 100).toFixed(0)}%`}
    </text>
  );
};

export default function AdminAnalytics() {
  const totalStudents = 5;
  const avgAttendance = Math.round(MOCK_STUDENTS.reduce((s, st) => s + st.attendance, 0) / MOCK_STUDENTS.length);
  const atRiskCount = MOCK_STUDENTS.filter(s => s.riskLevel === 'red').length;

  return (
    <div className="fade-in-up">
      <PageHeader title="Organization Analytics" subtitle="Platform-wide academic intelligence · refreshed every 24h" />

      {/* Stats */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '24px' }}>
        <StatCard label="Total Students" value={totalStudents} sub="Active this semester" color="#4f8ef7" icon={Users} />
        <StatCard label="Average Attendance" value={`${avgAttendance}%`} sub="Across all classes" color="#8b5cf6" icon={TrendingUp} trend={-4} />
        <StatCard label="At-Risk Students" value={atRiskCount} sub="Risk score > 70" color="#ef4444" icon={AlertTriangle} />
        <StatCard label="Open Disputes" value={2} sub="Pending admin action" color="#f59e0b" icon={CheckCircle2} />
      </div>

      {/* Charts row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.5fr', gap: '20px', marginBottom: '24px' }}>
        {/* Pie chart */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '4px' }}>Risk Distribution</div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '12px' }}>All active students</div>
          <ResponsiveContainer width="100%" height={180}>
            <PieChart>
              <Pie data={riskDist} cx="50%" cy="50%" innerRadius={50} outerRadius={80} dataKey="value" labelLine={false} label={<CustomPieLabel />}>
                {riskDist.map((entry, i) => <Cell key={i} fill={entry.color} />)}
              </Pie>
              <Tooltip contentStyle={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: '12px' }} />
            </PieChart>
          </ResponsiveContainer>
          <div style={{ display: 'flex', justifyContent: 'center', gap: '16px', marginTop: '8px' }}>
            {riskDist.map((d) => (
              <div key={d.name} style={{ display: 'flex', alignItems: 'center', gap: '5px' }}>
                <div style={{ width: '8px', height: '8px', borderRadius: '50%', background: d.color }} />
                <span style={{ fontSize: '10px', color: 'var(--text-muted)' }}>{d.name} ({d.value})</span>
              </div>
            ))}
          </div>
        </div>

        {/* Attendance trend */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '4px' }}>Attendance Trend</div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '16px' }}>Average % over last 5 months</div>
          <ResponsiveContainer width="100%" height={180}>
            <AreaChart data={attendanceTrend}>
              <defs>
                <linearGradient id="attGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#4f8ef7" stopOpacity={0.2} />
                  <stop offset="95%" stopColor="#4f8ef7" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
              <XAxis dataKey="month" tick={{ fill: '#8b8ba0', fontSize: 10 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: '#8b8ba0', fontSize: 10 }} axisLine={false} tickLine={false} domain={[60, 100]} />
              <Tooltip contentStyle={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: '12px' }} />
              <Area type="monotone" dataKey="avg" stroke="#4f8ef7" fill="url(#attGrad)" strokeWidth={2} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Branch performance */}
      <div className="card" style={{ padding: '20px' }}>
        <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '16px' }}>Attendance by Section</div>
        <ResponsiveContainer width="100%" height={160}>
          <BarChart data={branchData}>
            <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
            <XAxis dataKey="branch" tick={{ fill: '#8b8ba0', fontSize: 11 }} axisLine={false} tickLine={false} />
            <YAxis tick={{ fill: '#8b8ba0', fontSize: 10 }} axisLine={false} tickLine={false} domain={[60, 100]} />
            <Tooltip contentStyle={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '8px', fontSize: '12px' }} />
            <Bar dataKey="avg" fill="#8b5cf6" radius={[4, 4, 0, 0]} />
          </BarChart>
        </ResponsiveContainer>
      </div>
    </div>
  );
}

import React from 'react';
import useAppStore, { MOCK_STUDENTS } from '../../store';
import { StatCard, PageHeader, RiskBadge, ProgressBar } from '../../components/UI';
import {
  RadarChart, PolarGrid, PolarAngleAxis, Radar, ResponsiveContainer,
  AreaChart, Area, XAxis, YAxis, Tooltip, CartesianGrid
} from 'recharts';
import { Activity, BookOpen, Code2, Bell, Zap, TrendingUp } from 'lucide-react';

const student = MOCK_STUDENTS[0];

const radarData = [
  { subject: 'DSA', score: 72 },
  { subject: 'OS', score: 58 },
  { subject: 'DBMS', score: 81 },
  { subject: 'CN', score: 63 },
  { subject: 'ML', score: 45 },
];

const activityData = [
  { day: 'Mon', events: 8 },
  { day: 'Tue', events: 12 },
  { day: 'Wed', events: 3 },
  { day: 'Thu', events: 0 },
  { day: 'Fri', events: 0 },
  { day: 'Sat', events: 2 },
  { day: 'Sun', events: 5 },
];

const CustomTooltip = ({ active, payload }) => {
  if (active && payload?.length) {
    return (
      <div style={{ background: 'var(--bg-elevated)', border: '1px solid var(--border)', borderRadius: '8px', padding: '8px 12px', fontSize: '12px' }}>
        <div style={{ color: 'var(--text-primary)', fontWeight: '600' }}>{payload[0].value} events</div>
      </div>
    );
  }
  return null;
};

export default function StudentDashboard() {
  return (
    <div className="fade-in-up">
      <PageHeader
        title={`Good morning, ${student.name.split(' ')[0]} 👋`}
        subtitle="Here's your academic snapshot for today."
      />

      {/* Nudge card */}
      {student.nudge && (
        <div className="nudge-card" style={{ padding: '14px 18px', marginBottom: '24px', display: 'flex', alignItems: 'flex-start', gap: '12px' }}>
          <div style={{ width: '32px', height: '32px', background: 'rgba(79,142,247,0.15)', borderRadius: '8px', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            <Zap size={15} color="#4f8ef7" />
          </div>
          <div>
            <div style={{ fontSize: '11px', fontWeight: '600', color: '#4f8ef7', marginBottom: '2px' }}>Personal nudge</div>
            <div style={{ fontSize: '13px', color: 'var(--text-primary)', lineHeight: '1.5' }}>{student.nudge}</div>
          </div>
        </div>
      )}

      {/* Stats row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '16px', marginBottom: '24px' }}>
        <StatCard label="Attendance" value={`${student.attendance}%`} sub="This semester" color={student.attendance < 75 ? '#ef4444' : '#22c55e'} icon={Activity} trend={-8} />
        <StatCard label="Roadmap Progress" value="2/6" sub="Nodes completed" color="#8b5cf6" icon={TrendingUp} />
        <StatCard label="LeetCode Problems" value={student.codingStats.solved} sub={`Streak: ${student.codingStats.streak} days`} color="#f59e0b" icon={Code2} />
        <StatCard label="Pending Assignments" value="2" sub="1 overdue" color="#ef4444" icon={BookOpen} />
      </div>

      {/* Charts row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '24px' }}>
        {/* Radar chart */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '4px' }}>Subject Performance</div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '16px' }}>Unit 2 marks · out of 100</div>
          <ResponsiveContainer width="100%" height={200}>
            <RadarChart data={radarData}>
              <PolarGrid stroke="rgba(255,255,255,0.05)" />
              <PolarAngleAxis dataKey="subject" tick={{ fill: '#8b8ba0', fontSize: 11 }} />
              <Radar dataKey="score" stroke="#4f8ef7" fill="#4f8ef7" fillOpacity={0.15} strokeWidth={2} dot={{ fill: '#4f8ef7', r: 3 }} />
            </RadarChart>
          </ResponsiveContainer>
        </div>

        {/* Activity chart */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '4px' }}>Weekly Activity</div>
          <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '16px' }}>Platform events this week</div>
          <ResponsiveContainer width="100%" height={200}>
            <AreaChart data={activityData}>
              <defs>
                <linearGradient id="actGrad" x1="0" y1="0" x2="0" y2="1">
                  <stop offset="5%" stopColor="#8b5cf6" stopOpacity={0.25} />
                  <stop offset="95%" stopColor="#8b5cf6" stopOpacity={0} />
                </linearGradient>
              </defs>
              <CartesianGrid strokeDasharray="3 3" stroke="rgba(255,255,255,0.04)" />
              <XAxis dataKey="day" tick={{ fill: '#8b8ba0', fontSize: 10 }} axisLine={false} tickLine={false} />
              <YAxis tick={{ fill: '#8b8ba0', fontSize: 10 }} axisLine={false} tickLine={false} />
              <Tooltip content={<CustomTooltip />} />
              <Area type="monotone" dataKey="events" stroke="#8b5cf6" fill="url(#actGrad)" strokeWidth={2} />
            </AreaChart>
          </ResponsiveContainer>
        </div>
      </div>

      {/* Bottom row */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        {/* Subject bars */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '16px' }}>Subject Breakdown</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '14px' }}>
            {Object.entries(student.marks).map(([sub, score]) => (
              <div key={sub}>
                <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '6px' }}>
                  <span style={{ fontSize: '12px', fontWeight: '500' }}>{sub}</span>
                  <span style={{ fontSize: '12px', color: score < 60 ? '#ef4444' : score < 75 ? '#f59e0b' : '#22c55e', fontWeight: '600' }}>{score}%</span>
                </div>
                <ProgressBar value={score} color={score < 60 ? '#ef4444' : score < 75 ? '#f59e0b' : '#22c55e'} height={5} />
              </div>
            ))}
          </div>
        </div>

        {/* Assignments */}
        <div className="card" style={{ padding: '20px' }}>
          <div style={{ fontSize: '13px', fontWeight: '600', marginBottom: '16px' }}>Recent Assignments</div>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
            {[
              { title: 'Graph Traversal Problems', subject: 'DSA', deadline: 'Apr 1', status: 'pending' },
              { title: 'ER Diagram — Hospital DB', subject: 'DBMS', deadline: 'Mar 30', status: 'submitted' },
              { title: 'Process Scheduling Sim', subject: 'OS', deadline: 'Mar 28', status: 'late' },
            ].map((a, i) => (
              <div key={i} style={{ display: 'flex', alignItems: 'center', gap: '12px', padding: '10px 12px', background: 'var(--bg-elevated)', borderRadius: '8px' }}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: '12px', fontWeight: '500', marginBottom: '2px', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>{a.title}</div>
                  <div style={{ fontSize: '10px', color: 'var(--text-muted)' }}>{a.subject} · Due {a.deadline}</div>
                </div>
                <span className={a.status === 'submitted' ? 'badge-green' : a.status === 'late' ? 'badge-red' : 'badge-yellow'} style={{ padding: '2px 8px', borderRadius: '99px', fontSize: '10px', fontWeight: '600', whiteSpace: 'nowrap' }}>
                  {a.status}
                </span>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { PageHeader, RiskBadge } from '../../components/UI';
import { MOCK_STUDENTS } from '../../store';
import { Bell, Eye } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const ALERTS = [
  { student: MOCK_STUDENTS[0], message: 'Last active 5 days ago, attendance 62%, recent marks dropped 20%.', time: '2h ago', severity: 'red' },
  { student: MOCK_STUDENTS[3], message: 'Attendance dropped to 71%, 3 assignments late this month.', time: '8h ago', severity: 'yellow' },
];

export default function TeacherAlerts() {
  const navigate = useNavigate();
  return (
    <div className="fade-in-up" style={{ maxWidth: '680px' }}>
      <PageHeader title="Risk Alerts" subtitle="Students flagged by the wellbeing engine — no self-reporting, purely behavioral" />

      <div style={{ marginBottom: '20px', padding: '12px 16px', background: 'rgba(239,68,68,0.06)', border: '1px solid rgba(239,68,68,0.18)', borderRadius: '10px', fontSize: '12px', color: 'var(--text-secondary)', lineHeight: '1.6' }}>
        <strong style={{ color: '#ef4444' }}>How alerts work:</strong> The wellbeing engine runs nightly, scoring each student on behavioral signals — activity gaps, late submissions, attendance drops, and marks trends. No mood surveys. No self-reporting. Just observable patterns.
      </div>

      <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
        {ALERTS.map((alert, i) => (
          <div key={i} className="card" style={{ padding: '16px 20px', borderLeft: `3px solid ${alert.severity === 'red' ? '#ef4444' : '#f59e0b'}` }}>
            <div style={{ display: 'flex', alignItems: 'flex-start', gap: '14px' }}>
              <div style={{ width: '36px', height: '36px', borderRadius: '50%', background: alert.severity === 'red' ? 'rgba(239,68,68,0.15)' : 'rgba(245,158,11,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '12px', fontWeight: '700', color: alert.severity === 'red' ? '#ef4444' : '#f59e0b', flexShrink: 0 }}>
                {alert.student.name.split(' ').map(n => n[0]).join('')}
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '8px', flexWrap: 'wrap', marginBottom: '4px' }}>
                  <span style={{ fontSize: '13px', fontWeight: '600' }}>{alert.student.name}</span>
                  <RiskBadge level={alert.severity} score={alert.student.riskScore} />
                  <span style={{ fontSize: '10px', color: 'var(--text-muted)', marginLeft: 'auto' }}>{alert.time}</span>
                </div>
                <p style={{ fontSize: '12px', color: 'var(--text-secondary)', lineHeight: '1.5', marginBottom: '12px' }}>{alert.message}</p>
                <div style={{ display: 'flex', gap: '8px' }}>
                  <button className="btn btn-ghost" onClick={() => navigate(`/teacher/student/${alert.student.id}`)} style={{ fontSize: '11px', padding: '5px 12px' }}>
                    <Eye size={12} /> View Student
                  </button>
                </div>
              </div>
            </div>
          </div>
        ))}

        <div style={{ textAlign: 'center', padding: '16px', fontSize: '12px', color: 'var(--text-muted)' }}>
          Algorithms run at midnight · Next check in 18 hours
        </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import useAppStore, { MOCK_STUDENTS } from '../../store';
import { PageHeader, RiskBadge } from '../../components/UI';
import { Search, ChevronRight, AlertTriangle, Users, TrendingDown } from 'lucide-react';

const CLASSES = [
  { id: 'CSE-A', name: 'CSE Section A', semester: 6, branch: 'CSE', count: 4 },
  { id: 'CSE-B', name: 'CSE Section B', semester: 6, branch: 'CSE', count: 1 },
];

export default function TeacherClasses() {
  const [selectedClass, setSelectedClass] = useState(null);
  const [search, setSearch] = useState('');
  const [sortBy, setSortBy] = useState('risk');
  const navigate = useNavigate();

  const classStudents = MOCK_STUDENTS.filter((s) =>
    !selectedClass || s.section === selectedClass.id.replace('CSE-', '')
  );

  const filtered = classStudents
    .filter((s) => s.name.toLowerCase().includes(search.toLowerCase()) || s.rollNo.toLowerCase().includes(search.toLowerCase()))
    .sort((a, b) => {
      if (sortBy === 'risk') return b.riskScore - a.riskScore;
      if (sortBy === 'attendance') return a.attendance - b.attendance;
      if (sortBy === 'name') return a.name.localeCompare(b.name);
      return 0;
    });

  const riskCounts = { red: MOCK_STUDENTS.filter(s => s.riskLevel === 'red').length, yellow: MOCK_STUDENTS.filter(s => s.riskLevel === 'yellow').length, green: MOCK_STUDENTS.filter(s => s.riskLevel === 'green').length };

  if (!selectedClass) {
    return (
      <div className="fade-in-up">
        <PageHeader title="My Classes" subtitle="Select a class to view student analytics and risk scores" />
        {/* Summary pills */}
        <div style={{ display: 'flex', gap: '12px', marginBottom: '24px', flexWrap: 'wrap' }}>
          {[
            { label: 'At Risk', count: riskCounts.red, color: '#ef4444' },
            { label: 'Watching', count: riskCounts.yellow, color: '#f59e0b' },
            { label: 'On Track', count: riskCounts.green, color: '#22c55e' },
          ].map(({ label, count, color }) => (
            <div key={label} style={{ padding: '10px 18px', background: `${color}10`, border: `1px solid ${color}25`, borderRadius: '10px', display: 'flex', alignItems: 'center', gap: '8px' }}>
              <span style={{ fontSize: '18px', fontWeight: '700', fontFamily: 'Space Grotesk, sans-serif', color }}>{count}</span>
              <span style={{ fontSize: '12px', color: 'var(--text-secondary)' }}>{label}</span>
            </div>
          ))}
        </div>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))', gap: '16px' }}>
          {CLASSES.map((cls) => {
            const students = MOCK_STUDENTS.filter((s) => s.section === cls.id.replace('CSE-', ''));
            const redCount = students.filter((s) => s.riskLevel === 'red').length;
            return (
              <div key={cls.id} className="card" style={{ padding: '20px', cursor: 'pointer' }} onClick={() => setSelectedClass(cls)}>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: '14px' }}>
                  <div style={{ width: '40px', height: '40px', background: 'rgba(79,142,247,0.1)', borderRadius: '10px', display: 'flex', alignItems: 'center', justifyContent: 'center' }}>
                    <Users size={18} color="#4f8ef7" />
                  </div>
                  {redCount > 0 && (
                    <span style={{ display: 'flex', alignItems: 'center', gap: '4px', fontSize: '11px', color: '#ef4444', fontWeight: '600' }}>
                      <AlertTriangle size={11} /> {redCount} at risk
                    </span>
                  )}
                </div>
                <div style={{ fontSize: '15px', fontWeight: '700', marginBottom: '2px' }}>{cls.name}</div>
                <div style={{ fontSize: '11px', color: 'var(--text-muted)', marginBottom: '14px' }}>Semester {cls.semester} · {cls.count} students</div>
                <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
                  <span style={{ fontSize: '12px', color: '#4f8ef7' }}>View class →</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  return (
    <div className="fade-in-up">
      <PageHeader
        title={selectedClass.name}
        subtitle={`Semester ${selectedClass.semester} · Students sorted by risk score`}
        action={
          <button className="btn btn-ghost" onClick={() => setSelectedClass(null)} style={{ fontSize: '12px' }}>← All Classes</button>
        }
      />

      {/* Controls */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '16px', flexWrap: 'wrap' }}>
        <div style={{ position: 'relative', flex: 1, minWidth: '200px' }}>
          <Search size={13} style={{ position: 'absolute', left: '10px', top: '50%', transform: 'translateY(-50%)', color: 'var(--text-muted)' }} />
          <input className="input" placeholder="Search students..." value={search} onChange={(e) => setSearch(e.target.value)} style={{ paddingLeft: '30px' }} />
        </div>
        <select className="input" value={sortBy} onChange={(e) => setSortBy(e.target.value)} style={{ width: 'auto', minWidth: '140px' }}>
          <option value="risk">Sort: Risk Score</option>
          <option value="attendance">Sort: Attendance ↑</option>
          <option value="name">Sort: Name</option>
        </select>
      </div>

      {/* Student table */}
      <div className="card" style={{ overflow: 'hidden' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse' }}>
          <thead>
            <tr className="table-header">
              {['Student', 'Roll No', 'Risk Level', 'Attendance', 'Last Active', 'Marks Avg', ''].map((h) => (
                <th key={h} style={{ padding: '10px 14px', textAlign: 'left', fontSize: '11px', fontWeight: '600', color: 'var(--text-muted)', whiteSpace: 'nowrap' }}>{h}</th>
              ))}
            </tr>
          </thead>
          <tbody>
            {filtered.map((s) => {
              const avgMark = Math.round(Object.values(s.marks).reduce((a, b) => a + b, 0) / Object.values(s.marks).length);
              return (
                <tr key={s.id} className="table-row" style={{ cursor: 'pointer' }} onClick={() => navigate(`/teacher/student/${s.id}`)}>
                  <td style={{ padding: '12px 14px' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
                      <div style={{ width: '30px', height: '30px', borderRadius: '50%', background: s.riskLevel === 'red' ? 'rgba(239,68,68,0.15)' : s.riskLevel === 'yellow' ? 'rgba(245,158,11,0.15)' : 'rgba(34,197,94,0.15)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: '11px', fontWeight: '700', color: s.riskLevel === 'red' ? '#ef4444' : s.riskLevel === 'yellow' ? '#f59e0b' : '#22c55e', flexShrink: 0 }}>
                        {s.name.split(' ').map(n => n[0]).join('')}
                      </div>
                      <span style={{ fontSize: '13px', fontWeight: '500' }}>{s.name}</span>
                    </div>
                  </td>
                  <td style={{ padding: '12px 14px', fontSize: '12px', color: 'var(--text-secondary)' }}>{s.rollNo}</td>
                  <td style={{ padding: '12px 14px' }}><RiskBadge level={s.riskLevel} score={s.riskScore} /></td>
                  <td style={{ padding: '12px 14px', fontSize: '12px', fontWeight: '600', color: s.attendance < 75 ? '#ef4444' : 'var(--text-primary)' }}>{s.attendance}%</td>
                  <td style={{ padding: '12px 14px', fontSize: '12px', color: 'var(--text-muted)' }}>{s.lastActive}</td>
                  <td style={{ padding: '12px 14px', fontSize: '12px', fontWeight: '600', color: avgMark < 60 ? '#ef4444' : avgMark < 75 ? '#f59e0b' : '#22c55e' }}>{avgMark}%</td>
                  <td style={{ padding: '12px 14px' }}><ChevronRight size={14} color="var(--text-muted)" /></td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>
    </div>
  );
}
